class Solution {
public:
    int sumOfDigits(vector<int>& nums) {
        int m = *min_element(nums.begin(), nums.end());
        int s = 0;
        while (m) { s += m % 10; m /= 10; }
        return s % 2 == 0 ? 1 : 0;
    }
};

c.java:
class Solution {
    public int sumOfDigits(int[] nums) {
        int m = Integer.MAX_VALUE;
        for (int x : nums) m = Math.min(m, x);
        int s = 0;
        while (m > 0) { s += m % 10; m /= 10; }
        return s % 2 == 0 ? 1 : 0;
    }
}

