class Solution {
public:
    int sumOfDigits(vector<int>& nums) {
        int m = *min_element(nums.begin(), nums.end());
        int s = 0;
        for (char c : to_string(m)) s += c - '0';
        return s % 2 == 0 ? 1 : 0;
    }
};

c.java:
class Solution {
    public int sumOfDigits(int[] nums) {
        int m = Integer.MAX_VALUE;
        for (int x : nums) m = Math.min(m, x);
        int s = 0;
        for (char c : String.valueOf(m).toCharArray()) s += c - '0';
        return s % 2 == 0 ? 1 : 0;
    }
}

